<?php namespace App\Filament\Resources\StudentSocialPassportResource\RelationManagers;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;class SupportsRelationManager extends RelationManager{protected static string $relationship='supports';protected static ?string $title='Меры поддержки';public static function form(Form $f):Form{return $f->schema([Forms\Components\TextInput::make('support_type')->label('Мера поддержки')->required(),Forms\Components\TextInput::make('basis')->label('Основание'),Forms\Components\DatePicker::make('starts_on')->label('С'),Forms\Components\DatePicker::make('ends_on')->label('По'),Forms\Components\Textarea::make('note')->label('Примечание')]);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('support_type')->label('Мера'),Tables\Columns\TextColumn::make('basis')->label('Основание'),Tables\Columns\TextColumn::make('starts_on')->label('С')->date('d.m.Y'),Tables\Columns\TextColumn::make('ends_on')->label('По')->date('d.m.Y'),Tables\Columns\BadgeColumn::make('status')->label('Статус')])->headerActions([Tables\Actions\CreateAction::make()->label('Добавить меру')->mutateFormDataUsing(fn($d)=>$d+['status'=>'active','created_by'=>auth()->id()])])->actions([Tables\Actions\EditAction::make()]);}}